contracts/Ships.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

// import "hardhat/console.sol";
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

// TODO: CRITICAL Confirm which reentrancy guard to use
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
// import "@openzeppelin/contracts/utils/ReentrancyGuardTransient.sol";

import "./Types.sol";
import "./IRenderer.sol";
import "./IRandomManager.sol";
import "./IGenerateNewShip.sol";
import "./IUniversalCredits.sol";
import "./IShipAttributes.sol";
import "./IDroneEnergyCores.sol";

contract Ships is ERC721, Ownable, ReentrancyGuard {
    using EnumerableSet for EnumerableSet.UintSet;

    mapping(uint => Ship) public ships;
    uint public shipCount;

    mapping(address => EnumerableSet.UintSet) private shipsOwned;
    mapping(address => uint256) public lastClaimTimestamp;
    mapping(address => uint) public amountPurchased;

    // 4 weeks in seconds (28 days * 24 hours * 60 minutes * 60 seconds)
    uint256 public claimCooldownPeriod = 28 days;

    mapping(address => uint) public referralCount;

    // Hardcoded referral tiers (saves bytecode size)
    // Stages: 100, 1000, 10000, 50000, 100000 ships sold
    // Percentages: 0%, 10%, 20%, 35%, 50%

    error NotAuthorized(address);
    error NotYourShip(uint);
    error ShipDestroyed();
    error MintPaused();
    error ShipConstructed(uint);
    error ShipInFleet(uint);
    error InsufficientPurchases(address);
    error InvalidPurchase(uint _tier, uint _amount);
    error ArrayLengthMismatch();
    error ShipAlreadyDestroyed(uint);
    error CannotRecycleFreeShip(uint);
    error InvalidVariant(uint16);
    error ReferralTransferFailed();
    error WithdrawalFailed();
    error ClaimCooldownNotPassed();

    struct ContractConfig {
        address gameAddress;
        address lobbyAddress;
        address fleetsAddress;
        IRenderMetadata metadataRenderer;
        IRandomManager randomManager;
        IGenerateNewShip shipGenerator;
        IShipAttributes shipAttributes;
    }

    ContractConfig public config;

    uint8[] public tierShips;
    uint[] public tierPrices;

    bool public paused;

    uint16 public maxVariant = 1;

    event MetadataUpdate(uint256 _tokenId);

    // ERC-5192 Minimal Soulbound extension (no extra storage required)
    // See: https://eips.ethereum.org/EIPS/eip-5192
    event Locked(uint256 tokenId);
    event Unlocked(uint256 tokenId);

    mapping(address => bool) public isAllowedToCreateShips;

    // TODO: Should variants have different weapons or props?

    IUniversalCredits public universalCredits;
    IDroneEnergyCores public droneEnergyCores;
    uint public recycleReward = 0.1 ether; // 0.1 UC tokens

    // Only Owner TODO
    // Withdrawal

    constructor(
        address _renderer
    ) ERC721("Void Tactics Ships", "SHIP") Ownable(msg.sender) {
        config.metadataRenderer = IRenderMetadata(_renderer);

        // Variant 0 has no modifiers, already exists as zeroes

        tierShips = [5, 11, 22, 40, 60];
        //              0%, 10%, 15%, 20%, 25%
        tierPrices = [
            4.99 ether,
            9.99 ether,
            19.99 ether,
            34.99 ether,
            49.99 ether
        ];
    }

    /**
     * @dev PUBLIC
     */

    // For purchases with ERC20s such as Universal Credits
    // or anything else I think of

    function createShips(
        address _to,
        uint _amount,
        uint16 _variant,
        uint8 _tier
    ) external {
        if (!isAllowedToCreateShips[msg.sender]) {
            revert NotAuthorized(msg.sender);
        }

        uint8 tierRankCount = _tier + 1;
        for (uint i = 0; i < _amount; i++) {
            if (i < tierRankCount) {
                uint8 rank = _tier + 1 - uint8(i);
                _mintShip(_to, _variant, _getKillsForRank(rank));
            } else {
                _mintShip(_to, _variant, 0);
            }
        }

        // TODO: CRITICAL -> Evaluate side effects of this

        amountPurchased[_to] += _amount;
    }

    function purchaseWithFlow(
        address _to,
        uint8 _tier,
        address _referral,
        uint16 _variant
    ) external payable nonReentrant {
        if (msg.value != tierPrices[_tier]) {
            revert InvalidPurchase(_tier, msg.value);
        }

        uint totalShips = tierShips[_tier];
        uint8 tierRankCount = _tier + 1;

        for (uint i = 0; i < totalShips; i++) {
            if (i < tierRankCount) {
                uint8 rank = uint8(_tier + 1 - i);
                _mintShip(_to, _variant, _getKillsForRank(rank));
            } else {
                _mintShip(_to, _variant, 0);
            }
        }

        if (_referral != address(0)) {
            _processReferral(_referral, totalShips, tierPrices[_tier]);
        }

        amountPurchased[_to] += totalShips;
    }

    function constructShips(uint[] calldata _ids) external {
        for (uint i = 0; i < _ids.length; i++) {
            constructShip(_ids[i]);
        }
    }

    function constructAllMyShips() external {
        uint[] memory ids = shipsOwned[msg.sender].values();
        for (uint i = 0; i < ids.length; i++) {
            if (!ships[ids[i]].shipData.constructed) {
                constructShip(ids[i]);
            }
        }
    }

    // Used for bonuses, special ships, events, etc.
    // TODO CRITICAL:
    // This allows players to predict which ships to overwrite
    // with special ships.
    // I don't think I care, but should I?
    function customizeShip(uint _id, Ship calldata _ship) external {
        if (!isAllowedToCreateShips[msg.sender]) {
            revert NotAuthorized(msg.sender);
        }

        Ship storage ship = ships[_id];
        _applyShipCustomization(ship, _id, _ship);
    }

    // Used for minting predefined/specific ships in one call for authorized callers.
    function createSpecificShip(
        address _to,
        Ship calldata _ship
    ) external returns (uint) {
        if (!isAllowedToCreateShips[msg.sender]) {
            revert NotAuthorized(msg.sender);
        }

        _mintShip(_to, _ship.traits.variant, 0);
        uint newShipId = shipCount;
        Ship storage ship = ships[newShipId];
        _applyShipCustomization(ship, newShipId, _ship);
        return newShipId;
    }

    function _applyShipCustomization(
        Ship storage ship,
        uint _id,
        Ship calldata _ship
    ) internal {
        emit MetadataUpdate(_id);

        if (ship.shipData.timestampDestroyed != 0) {
            revert ShipDestroyed();
        }

        if (ship.shipData.inFleet) {
            revert ShipInFleet(_id);
        }

        // Calculate modifications by comparing old and new
        uint16 amountModified = _calculateModifications(ship, _ship);

        // Update ship properties (preserve immutable traits like serialNumber)
        ship.name = _ship.name;
        ship.traits.accuracy = _ship.traits.accuracy;
        ship.traits.hull = _ship.traits.hull;
        ship.traits.speed = _ship.traits.speed;
        // NOTE: traits.variant is not bounds-checked against maxVariant here.
        // DroneYard.validateShip is currently the only caller-side enforcement
        // of that bound (variant == 0 or > maxVariant reverts there). Ships.sol
        // has almost no bytecode headroom left (see
        // docs/ShipsSizeOptimizationAnalysis.md for identified savings), so a
        // second check here was deliberately deferred. Any future
        // isAllowedToCreateShips-authorized caller that lets end users set
        // variant must enforce this bound itself until there's room to
        // centralize it.
        ship.traits.variant = _ship.traits.variant;
        ship.traits.colors = _ship.traits.colors;
        ship.equipment = _ship.equipment;
        // Allow authorized custom templates (e.g. tutorial ships) to define rank.
        ship.shipData.shipsDestroyed = _ship.shipData.shipsDestroyed;
        ship.shipData.isFreeShip = _ship.shipData.isFreeShip;

        ship.shipData.shiny = _ship.shipData.shiny;

        // Update modified amount (add to existing if constructed, set if not)
        if (ship.shipData.constructed) {
            ship.shipData.modified += amountModified;
        } else {
            ship.shipData.modified = amountModified;
            ship.shipData.constructed = true;
        }

        _setCostOfShip(_id);
    }

    function _calculateModifications(
        Ship storage _currentShip,
        Ship memory _newShip
    ) internal view returns (uint16) {
        uint16 modifications = 0;

        // Count equipment changes (add 1 for each changed property)
        if (
            _currentShip.equipment.mainWeapon != _newShip.equipment.mainWeapon
        ) {
            modifications++;
        }
        if (_currentShip.equipment.armor != _newShip.equipment.armor) {
            modifications++;
        }
        if (_currentShip.equipment.shields != _newShip.equipment.shields) {
            modifications++;
        }
        if (_currentShip.equipment.special != _newShip.equipment.special) {
            modifications++;
        }

        // Calculate trait changes (total absolute difference)
        uint8 accuracyDiff = _newShip.traits.accuracy >
            _currentShip.traits.accuracy
            ? _newShip.traits.accuracy - _currentShip.traits.accuracy
            : _currentShip.traits.accuracy - _newShip.traits.accuracy;
        uint8 hullDiff = _newShip.traits.hull > _currentShip.traits.hull
            ? _newShip.traits.hull - _currentShip.traits.hull
            : _currentShip.traits.hull - _newShip.traits.hull;
        uint8 speedDiff = _newShip.traits.speed > _currentShip.traits.speed
            ? _newShip.traits.speed - _currentShip.traits.speed
            : _currentShip.traits.speed - _newShip.traits.speed;

        modifications += accuracyDiff + hullDiff + speedDiff;

        // Count shiny status change as 3 modifications
        if (_currentShip.shipData.shiny != _newShip.shipData.shiny) {
            modifications += 3;
        }

        // Count variant change as 3 modifications, matching shiny's weight
        if (_currentShip.traits.variant != _newShip.traits.variant) {
            modifications += 3;
        }

        return modifications;
    }

    function constructShip(uint _id) public {
        emit MetadataUpdate(_id);

        Ship storage newShip = ships[_id];

        if (newShip.owner != msg.sender) {
            revert NotYourShip(_id);
        }

        if (newShip.shipData.constructed) {
            revert ShipConstructed(_id);
        }

        uint64 randomBase = config.randomManager.fulfillRandomRequest(
            newShip.traits.serialNumber
        );

        Ship memory generatedShip = config.shipGenerator.generateShip(
            _id,
            newShip.traits.serialNumber,
            randomBase,
            newShip.traits.variant
        );

        // Copy generated ship data to storage
        // We already have variant, it was set at purchase
        // as was the serial number
        newShip.name = generatedShip.name;
        newShip.traits = generatedShip.traits;
        newShip.equipment = generatedShip.equipment;
        newShip.shipData.shiny = generatedShip.shipData.shiny;
        // Preserve existing kills if already set (tier-based purchases)
        if (newShip.shipData.shipsDestroyed == 0) {
            newShip.shipData.shipsDestroyed = generatedShip
                .shipData
                .shipsDestroyed;
        }
        newShip.shipData.constructed = true;
        // modified defaults to 0 (false) for regular construction

        _setCostOfShip(_id);
    }

    function setCostOfShip(uint _id) external {
        if (msg.sender != owner() && msg.sender != config.gameAddress) {
            revert NotAuthorized(msg.sender);
        }

        _setCostOfShip(_id);
    }

    /// @notice Permissionless: refresh cost and costsVersion for each id (minted ERC-721 tokens only; invalid ids corrupt storage).
    function syncShipCosts(uint[] calldata _ids) external {
        for (uint i; i < _ids.length; ++i) {
            _setCostOfShip(_ids[i]);
        }
    }

    function _setCostOfShip(uint _id) internal {
        Ship storage ship = ships[_id];
        if (ship.shipData.inFleet) {
            revert ShipInFleet(_id);
        }
        ship.shipData.costsVersion = config
            .shipAttributes
            .getCurrentCostsVersion();
        ship.shipData.cost = config.shipAttributes.calculateShipCost(ship);
    }

    /**
     * @dev Lobby and GameFunctions
     */

    function setInFleet(uint _id, bool _inFleet) external {
        if (
            msg.sender != config.lobbyAddress &&
            msg.sender != config.gameAddress &&
            msg.sender != config.fleetsAddress
        ) {
            revert NotAuthorized(msg.sender);
        }

        ships[_id].shipData.inFleet = _inFleet;

        // ERC-5192: Lock when added to fleet; unlock when removed (purely via events)
        if (_inFleet) emit Locked(_id);
        else emit Unlocked(_id);
    }

    /**
     * @dev INTERNAL
     */

    // Override erc721 update
    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal override(ERC721) returns (address) {
        // Cache storage reference to avoid repeated SLOADs
        Ship storage ship = ships[tokenId];
        address oldOwner = ship.owner;

        // Skip destroyed check for burning (when to is address(0))
        if (to != address(0)) {
            if (ship.shipData.timestampDestroyed != 0) {
                revert ShipDestroyed();
            }
        }

        // Always check if ship is in fleet
        if (ship.shipData.inFleet) {
            revert ShipInFleet(tokenId);
        }

        // Skip transfer check for minting (when oldOwner is address(0))
        if (oldOwner != address(0)) {
            if (amountPurchased[oldOwner] < 10) {
                revert InsufficientPurchases(oldOwner);
            }
            if (to != address(0) && amountPurchased[to] < 10) {
                revert InsufficientPurchases(to);
            }
            // Handle ownership list
            shipsOwned[oldOwner].remove(tokenId);
        }

        // Only add to shipsOwned if not burning
        if (to != address(0)) {
            shipsOwned[to].add(tokenId);
            ship.owner = to;
        }

        // ERC-5192: if burning (to == address(0)) emit Locked for final state
        if (to == address(0)) emit Locked(tokenId);

        return super._update(to, tokenId, auth);
    }

    function _getKillsForRank(uint8 rank) internal pure returns (uint16) {
        if (rank >= 6) return 1000;
        if (rank == 5) return 300;
        if (rank == 4) return 100;
        if (rank == 3) return 30;
        if (rank == 2) return 10;
        return 1;
    }

    function _mintShip(
        address _to,
        uint16 _variant,
        uint16 _shipsDestroyed
    ) internal {
        if (paused) {
            revert MintPaused();
        }

        if (_variant > maxVariant || _variant == 0) {
            revert InvalidVariant(_variant);
        }

        shipCount++;
        Ship storage newShip = ships[shipCount];
        newShip.id = shipCount;

        newShip.traits.serialNumber = config.randomManager.requestRandomness();
        newShip.traits.variant = _variant;
        if (_shipsDestroyed > 0) {
            newShip.shipData.shipsDestroyed = _shipsDestroyed;
        }

        _safeMint(_to, shipCount);

        // Set owner after minting to avoid check in _update
        newShip.owner = _to;

        // ERC-5192: Ships start unlocked (emit for indexers if desired)
        emit Unlocked(shipCount);
    }

    function _processReferral(
        address _referrer,
        uint _shipsSold,
        uint _salePrice
    ) internal {
        referralCount[_referrer] += _shipsSold;

        uint referralPercentage;
        uint totalSold = referralCount[_referrer];

        // Hardcoded referral tiers (stages: 100, 1000, 10000, 50000, 100000)
        // Percentages: 0%, 10%, 20%, 35%, 50%
        if (totalSold >= 100000) {
            referralPercentage = 50;
        } else if (totalSold >= 50000) {
            referralPercentage = 35;
        } else if (totalSold >= 10000) {
            referralPercentage = 20;
        } else if (totalSold >= 1000) {
            referralPercentage = 10;
        } else {
            referralPercentage = 0;
        }

        uint referralAmount = (_salePrice * referralPercentage) / 100;

        (bool success, ) = payable(_referrer).call{value: referralAmount}("");
        if (!success) revert ReferralTransferFailed();
    }

    /**
     * @dev OWNER
     */

    function setIsAllowedToCreateShips(
        address _address,
        bool _isAllowed
    ) public onlyOwner {
        isAllowedToCreateShips[_address] = _isAllowed;
    }

    // Decomposed from a single combined setTimestampDestroyed into two
    // primitives (this + recordKill) so ShipsRouter can orchestrate a kill
    // that spans this contract and AIShips.sol — the destroyed ship and the
    // destroyer ship no longer always live in the same contract's storage.
    // The DEC/UTC reward payout itself now lives entirely in ShipsRouter,
    // which is the only caller that can see both ships' owners regardless
    // of which contract holds them.
    function markDestroyed(uint _id) external returns (address ownerOut) {
        if (msg.sender != owner() && msg.sender != config.gameAddress) {
            revert NotAuthorized(msg.sender);
        }
        if (ships[_id].shipData.timestampDestroyed != 0) {
            revert ShipAlreadyDestroyed(_id);
        }
        ships[_id].shipData.timestampDestroyed = block.timestamp;

        // ERC-5192: Lock when destroyed
        emit Locked(_id);
        emit MetadataUpdate(_id);

        return ships[_id].owner;
    }

    function recordKill(uint _destroyerId) external returns (address ownerOut) {
        if (msg.sender != owner() && msg.sender != config.gameAddress) {
            revert NotAuthorized(msg.sender);
        }
        ships[_destroyerId].shipData.shipsDestroyed++;
        return ships[_destroyerId].owner;
    }

    function setPurchaseInfo(
        uint8[] calldata _tierShips,
        uint[] calldata _tierPrices
    ) external onlyOwner {
        if (_tierShips.length != _tierPrices.length) {
            revert ArrayLengthMismatch();
        }
        tierShips = _tierShips;
        tierPrices = _tierPrices;
    }

    function setConfig(
        address _gameAddress,
        address _lobbyAddress, // now SinglePlayerMatch's address — see DestroyRewardLib/ILobbiesOrchestratorCheck

        address _fleetsAddress,
        address _shipGenerator,
        address _randomManager,
        address _metadataRenderer,
        address _shipAttributes,
        address _universalCredits,
        address _droneEnergyCores
    ) public onlyOwner {
        config.gameAddress = _gameAddress;
        config.lobbyAddress = _lobbyAddress;
        config.fleetsAddress = _fleetsAddress;
        config.shipGenerator = IGenerateNewShip(_shipGenerator);
        config.randomManager = IRandomManager(_randomManager);
        config.metadataRenderer = IRenderMetadata(_metadataRenderer);
        config.shipAttributes = IShipAttributes(_shipAttributes);
        universalCredits = IUniversalCredits(_universalCredits);
        droneEnergyCores = IDroneEnergyCores(_droneEnergyCores);
    }

    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
    }

    function withdraw() external onlyOwner {
        (bool success, ) = payable(owner()).call{value: address(this).balance}(
            ""
        );
        if (!success) revert WithdrawalFailed();
    }

    function setMaxVariant(uint16 _maxVariant) external onlyOwner {
        maxVariant = _maxVariant;
    }

    function setRecycleReward(uint _newReward) external onlyOwner {
        recycleReward = _newReward;
    }

    function setClaimCooldownPeriod(
        uint256 _newCooldownPeriod
    ) public onlyOwner {
        claimCooldownPeriod = _newCooldownPeriod;
    }

    // function setShipModified(uint _id, bool _modified) public onlyOwner {
    //     Ship storage ship = ships[_id];
    //     if (ship.id == 0) {
    //         revert InvalidId();
    //     }
    //     ship.shipData.modified = _modified;
    //     emit MetadataUpdate(_id);
    // }

    function claimFreeShips(uint16 _variant) external {
        uint256 lastClaim = lastClaimTimestamp[msg.sender];
        uint256 currentTime = block.timestamp;

        // Check if 4 weeks have passed since last claim
        // Note: When lastClaim == 0 (first claim), currentTime (block.timestamp) will always be
        // much larger than claimCooldownPeriod (28 days), so the check won't revert for new users
        if (currentTime < lastClaim + claimCooldownPeriod) {
            revert ClaimCooldownNotPassed();
        }

        // Grant 10 free ships
        for (uint i = 0; i < 10; i++) {
            _mintShip(msg.sender, _variant, 0);
            // Mark the ship as free (shipCount was incremented in _mintShip, so it's the ID of the ship just minted)
            ships[shipCount].shipData.isFreeShip = true;
        }

        // Record the timestamp of this claim
        lastClaimTimestamp[msg.sender] = currentTime;
    }

    /**
     * @dev VIEW
     */

    function getShip(uint _id) external view returns (Ship memory) {
        return ships[_id];
    }

    // Used by game contract
    function isShipDestroyed(uint _id) external view returns (bool) {
        return ships[_id].shipData.timestampDestroyed != 0;
    }

    // ERC-5192: minimal interface view - derived from existing state
    // Not used by Opensea and other marketplaces, I don't think it's necessary to keep it.
    // function locked(uint256 tokenId) external view returns (bool) {
    //     Ship storage s = ships[tokenId];
    //     if (s.shipData.timestampDestroyed != 0) return true;
    //     return s.shipData.inFleet;
    // }

    function getPurchaseInfo()
        external
        view
        returns (uint8[] memory _tierShips, uint[] memory _tierPrices)
    {
        return (tierShips, tierPrices);
    }

    function tokenURI(uint _id) public view override returns (string memory) {
        return config.metadataRenderer.tokenURI(ships[_id]);
    }

    function getShipIdsOwned(
        address _owner
    ) external view returns (uint[] memory) {
        return shipsOwned[_owner].values();
    }

    // // TODO CRITICAL: This almost certainly needs to be paginated
    // function getShipsOwned(address _owner) public view returns (Ship[] memory) {
    //     uint[] memory ids = getShipIdsOwned(_owner);
    //     Ship[] memory shipsFetched = new Ship[](ids.length);
    //     for (uint i = 0; i < ids.length; i++) {
    //         shipsFetched[i] = ships[ids[i]];
    //     }
    //     return shipsFetched;
    // }

    function getShipsByIds(
        uint[] calldata _ids
    ) external view returns (Ship[] memory) {
        Ship[] memory shipsFetched = new Ship[](_ids.length);
        for (uint i = 0; i < _ids.length; i++) {
            shipsFetched[i] = ships[_ids[i]];
        }
        return shipsFetched;
    }

    /**
     * @dev PURE
     */

    // TODO: Do tiers need to be adjustable?
    function getTierOfTrait(uint _trait) external pure returns (uint8) {
        return _trait < 50 ? 0 : (_trait < 80 ? 1 : 2);
    }

    function shipBreaker(uint[] calldata _shipIds) external nonReentrant {
        uint totalReward = 0;

        for (uint i = 0; i < _shipIds.length; i++) {
            uint shipId = _shipIds[i];

            // Cache storage reference to avoid repeated SLOADs
            Ship storage s = ships[shipId];

            // Check if caller owns the ship
            // TODO: I'm 85% sure this is redundant.
            if (s.owner != msg.sender) {
                revert NotYourShip(shipId);
            }

            // Ships in a fleet must not be destroyed: _update's inFleet check would
            // revert the _burn call below anyway, but only after timestampDestroyed
            // has already been written — checking here keeps that write from ever
            // happening instead of relying on the burn's revert to undo it.
            if (s.shipData.inFleet) {
                revert ShipInFleet(shipId);
            }

            // Prevent recycling of free ships
            if (s.shipData.isFreeShip) {
                revert CannotRecycleFreeShip(shipId);
            }

            // Determine recycle reward based on destruction state PRIOR to this call
            bool wasDestroyed = s.shipData.timestampDestroyed != 0;
            uint rewardForThisShip = wasDestroyed
                ? (recycleReward >> 1) // Division by 2
                : recycleReward;

            // Mark ship as destroyed and burn it
            s.shipData.timestampDestroyed = block.timestamp;
            emit Locked(shipId);
            _burn(shipId);

            // Add to total reward
            totalReward += rewardForThisShip;
        }

        // Mint reward tokens to the owner
        if (totalReward > 0) {
            universalCredits.mint(msg.sender, totalReward);
        }
    }
}

contracts/ShipsRouter.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./Types.sol";
import "./IShips.sol";
import "./IAIShips.sol";
import "./Ships.sol";
import "./IUniversalCredits.sol";
import "./IDroneEnergyCores.sol";
import "./DestroyRewardLib.sol";

// Facade Game.sol/Fleets.sol/ShipAttributes.sol call instead of Ships.sol
// directly, so a single shipId space can resolve against two different
// backing stores: Ships.sol (real ERC-721 human ships) and AIShips.sol
// (pooled, non-NFT AI ships). Dispatch is purely numeric — any id at or
// above AI_SHIP_ID_OFFSET belongs to AIShips.sol, everything below belongs
// to Ships.sol — so Game.sol needs no source changes at all, only a
// constructor argument pointed here instead of at Ships.sol.
//
// setTimestampDestroyed is the one function that needs real orchestration:
// Ships.sol used to mark the destroyed ship, credit the destroyer, and pay
// the DEC/UTC reward all by indexing into its own storage for both ships.
// Once AI ships can live in a different contract than their destroyer (or
// vice versa), that combined logic has to live here instead, uniformly for
// both the pure-PvP case (both ids human) and the cross-contract case.
contract ShipsRouter is IShips, Ownable {
    uint public constant AI_SHIP_ID_OFFSET = 2 ** 128;

    Ships public ships; // human ships (real ERC-721)
    IAIShips public aiShips; // pooled AI ships (no ERC-721)
    IUniversalCredits public universalCredits;
    IDroneEnergyCores public droneEnergyCores;

    address public gameAddress;
    address public fleetsAddress;
    address public lobbyAddress; // SinglePlayerMatch — see DestroyRewardLib

    error NotAuthorized(address);

    constructor(
        address _ships,
        address _aiShips,
        address _universalCredits,
        address _droneEnergyCores
    ) Ownable(msg.sender) {
        ships = Ships(_ships);
        aiShips = IAIShips(_aiShips);
        universalCredits = IUniversalCredits(_universalCredits);
        droneEnergyCores = IDroneEnergyCores(_droneEnergyCores);
    }

    function setGameAddress(address _gameAddress) external onlyOwner {
        gameAddress = _gameAddress;
    }

    function setFleetsAddress(address _fleetsAddress) external onlyOwner {
        fleetsAddress = _fleetsAddress;
    }

    function setLobbyAddress(address _lobbyAddress) external onlyOwner {
        lobbyAddress = _lobbyAddress;
    }

    function _isAI(uint _id) internal pure returns (bool) {
        return _id >= AI_SHIP_ID_OFFSET;
    }

    function getShip(uint _id) external view returns (Ship memory) {
        return _isAI(_id) ? aiShips.getShip(_id) : ships.getShip(_id);
    }

    function isShipDestroyed(uint _id) external view returns (bool) {
        return _isAI(_id) ? aiShips.isShipDestroyed(_id) : ships.isShipDestroyed(_id);
    }

    // Ships.sol/AIShips.sol both whitelist this router as a caller, so this
    // router must enforce the same caller check Ships.sol used to apply
    // directly — otherwise any account could call through the router and
    // silently unlock/lock a ship it doesn't control, since the backing
    // contracts see the trusted router as msg.sender regardless of who
    // called the router itself.
    function setInFleet(uint _id, bool _inFleet) external {
        if (msg.sender != owner() && msg.sender != fleetsAddress) {
            revert NotAuthorized(msg.sender);
        }
        if (_isAI(_id)) {
            aiShips.setInFleet(_id, _inFleet);
        } else {
            ships.setInFleet(_id, _inFleet);
        }
    }

    function setTimestampDestroyed(uint _id, uint _destroyerId) external {
        if (msg.sender != owner() && msg.sender != gameAddress) {
            revert NotAuthorized(msg.sender);
        }

        address destroyedOwner = _isAI(_id)
            ? aiShips.markDestroyed(_id)
            : ships.markDestroyed(_id);

        address destroyerOwner = _isAI(_destroyerId)
            ? aiShips.recordKill(_destroyerId)
            : ships.recordKill(_destroyerId);

        if (destroyerOwner != address(0)) {
            DestroyRewardLib.payDestroyReward(
                lobbyAddress,
                destroyedOwner,
                destroyerOwner,
                ships.recycleReward() >> 2, // Division by 4
                universalCredits,
                droneEnergyCores
            );
        }
    }

    // The functions below are only ever exercised against real (human)
    // ships in production — DroneYard/ShipPurchaser/TutorialClaim stay
    // wired directly to Ships.sol, never through this router. They exist
    // here purely so this contract satisfies the IShips interface that
    // Game.sol's constructor expects.
    function createShips(
        address _to,
        uint _amount,
        uint16 _variant,
        uint8 _tier
    ) external {
        ships.createShips(_to, _amount, _variant, _tier);
    }

    function createSpecificShip(
        address _to,
        Ship calldata _ship
    ) external returns (uint) {
        return ships.createSpecificShip(_to, _ship);
    }

    function customizeShip(uint _id, Ship memory _ship) external {
        ships.customizeShip(_id, _ship);
    }

    function maxVariant() external view returns (uint16) {
        return ships.maxVariant();
    }

    function recycleReward() external view returns (uint) {
        return ships.recycleReward();
    }
}

contracts/Types.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

enum MainWeapon {
    Laser,
    Railgun,
    MissileLauncher,
    PlasmaCannon,
    future1,
    future2,
    future3,
    future4
}

// Reduces Damage, Does not Provide Hitpoints
enum Armor {
    None,
    Light,
    Medium,
    Heavy,
    future1,
    future2,
    future3,
    future4
}

// Reduces Damage, Does not Provide Hitpoints
enum Shields {
    None,
    Light,
    Medium,
    Heavy,
    future1,
    future2,
    future3,
    future4
}

enum Special {
    None,
    EMP,
    RepairDrones,
    FlakArray,
    future1,
    future2,
    future3,
    future4
}

// Single-player AI behavior tag, assigned per AIShipConfig (AIEncounters.sol)
// and looked up per minted AI ship (SinglePlayerMatch.shipArchetype) to pick
// which ordered priority-list of rules takeAITurn applies to that ship.
enum Archetype {
    Grunt, // shoot what's in range, else close distance
    Aggressor, // prioritize kills over safety, closes distance hard
    Sniper, // shoots at range, retreats rather than engaging adjacent
    Support, // heals the weakest ally in range (RepairDrones), hangs back
    Turtle, // seeks/holds scoring tiles, fights only opportunistically
    Rammer // faction-1 only: hunts 0-HP enemies to Ram, else shoots
}

// Declarative outcome of a resolver-backed faction ability (see
// IFactionAbilityResolver), applied by Game.sol without re-validating
// anything — the resolver owns all pre-dispatch checks for its ability.
// One entry per affected ship; a resolver may return any number of these.
// newRow/newCol double as the "relocate" flag: type(int16).min (an
// unreachable grid coordinate) means "don't move this ship". Fewer, denser
// fields keep the external-call ABI decode/encode Game.sol pays for as
// small as possible — this struct crosses a contract boundary every time.
struct SpecialEffect {
    uint shipId;
    int16 hullDelta; // negative = damage, positive = heal; capped at maxHullPoints
    int8 reactorTimerDelta; // added to reactorCriticalTimer; still auto-removes at >=3
    int16 newRow; // type(int16).min = no relocation
    int16 newCol;
    uint8 removalKind; // 0 = none, 1 = retreat, 2 = destroy (mirrors _removeShipFromGame's retreat/destroy flag)
}

// Raw Traits Will Never Change
struct Traits {
    uint256 serialNumber; // Id for random number in commit reveal
    Colors colors;
    uint16 variant; // Which art to use for the ship
    uint8 accuracy;
    uint8 hull; // Hitpoints
    uint8 speed;
}

struct Colors {
    uint16 h1;
    uint8 s1;
    uint8 l1;
    uint16 h2;
    uint8 s2;
    uint8 l2;
    uint16 h3;
    uint8 s3;
    uint8 l3;
}

struct Equipment {
    MainWeapon mainWeapon;
    Armor armor;
    Shields shields;
    Special special;
}

// Attributes Change on Version
// Attributes will live in the game contract
struct Attributes {
    uint16 version; // Attributes version not cost version
    uint8 range;
    uint8 gunDamage;
    uint8 hullPoints;
    uint8 maxHullPoints;
    uint8 movement;
    uint8 damageReduction;
    uint8 reactorCriticalTimer;
    uint8[] statusEffects;
}

// Grid position structure
struct Position {
    int16 row;
    int16 col;
}

// Scoring position structure with point value
struct ScoringPosition {
    int16 row;
    int16 col;
    uint8 points; // Number of points available on this tile
    bool onlyOnce; // Whether this tile can only be claimed once
}

// Ship position on the grid (including status for replay/visualization)
// status: 0 = alive, 1 = destroyed, 2 = fled
struct ShipPosition {
    uint shipId;
    Position position;
    bool isCreator;
    uint8 status;
}

// Game metadata - basic game identification and players
struct GameMetadata {
    uint gameId;
    uint lobbyId;
    address creator;
    address joiner;
    uint creatorFleetId;
    uint joinerFleetId;
    bool creatorGoesFirst;
    uint startedAt;
    address winner; // Winner of the game (zero address if game is not over OR if it was a draw)
    // True once _endGame has run. winner alone can't distinguish "not over" from
    // "ended in a draw" (both leave winner == address(0)), so this is the one
    // source of truth for "has this game ended." Packs into winner's storage
    // slot (address is 20 bytes, bool is 1), so this costs no extra slot.
    bool ended;
    // The contract that called startGame for this session (e.g. PvPMatch).
    // Only this address may call forceEndSession, and it's who Game.sol
    // calls back into (via IGameOrchestrator.onGameEnded) when the session
    // ends, so each game mode can decide what "ended" means for it without
    // core Game.sol needing to know about leaderboards/results contracts.
    address orchestrator;
}

// Game turn state - turn and timing related data
struct GameTurnState {
    address currentTurn;
    uint turnTime; // Time limit per turn in seconds
    uint turnStartTime; // When current turn started
    uint currentRound;
}

// Game grid dimensions
struct GameGridDimensions {
    int16 gridWidth;
    int16 gridHeight;
}

struct GameData {
    GameMetadata metadata;
    GameTurnState turnState;
    GameGridDimensions gridDimensions;
    uint maxScore; // Maximum score needed to win the game
    uint creatorScore; // Current score of the creator player
    uint joinerScore; // Current score of the joiner player
    LastMove lastMove; // Most recent move in the game
    // Keep all mappings in GameData
    mapping(uint => Attributes) shipAttributes; // shipId => attributes
    // Grid state - grid[row][column] = shipId (0 if empty)
    mapping(int16 row => mapping(int16 column => uint shipId)) grid;
    // Board position and status for each ship (status: 0 = alive, 1 = destroyed, 2 = fled)
    mapping(uint => ShipPosition) shipPositions; // shipId => position + status
    // Kill-credit tracking: target shipId => shipId of its last damager, scoped per
    // game (was a top-level Game.sol mapping shared across all games; a ship id
    // reused in a later game would inherit a stale entry from an earlier one).
    mapping(uint => uint) lastDamage;
    EnumerableSet.UintSet shipMovedThisRound; // movedShipIds in current round
    EnumerableSet.UintSet shipsWithZeroHP; // shipIds with 0 hull points
    // Store active ship IDs for each player to avoid repeated fleet calls
    mapping(address => EnumerableSet.UintSet) playerActiveShipIds; // player => shipIds
    // Round completion: use counts at round start so destroyed/retreated ships don't shrink the threshold
    uint[] goneShipIds; // shipIds that have been destroyed or retreated this round
    uint totalActiveShipsAtRoundStart; // set at start of each round
    uint shipsRemovedThisRound; // destroyed or retreated this round (incremented in _removeShipFromGame)
}

struct GameDataView {
    GameMetadata metadata;
    GameTurnState turnState;
    GameGridDimensions gridDimensions;
    uint maxScore; // Maximum score needed to win the game
    uint creatorScore; // Current score of the creator player
    uint joinerScore; // Current score of the joiner player
    LastMove lastMove; // Most recent move in the game
    // Ship data arrays
    uint[] shipIds;
    Attributes[] shipAttributes; // Combined array of all ship attributes indexed by ship ID
    ShipPosition[] shipPositions; // All ship positions on the grid
    // Active ship IDs for each player
    uint[] creatorActiveShipIds;
    uint[] joinerActiveShipIds;
    // Ships that have moved this round
    uint[] creatorMovedShipIds; // Creator ships that have moved this round
    uint[] joinerMovedShipIds; // Joiner ships that have moved this round
}

struct Ship {
    string name;
    uint id;
    Equipment equipment;
    Traits traits;
    ShipData shipData;
    address owner;
}

struct ShipData {
    uint32 shipsDestroyed; // +1 for Frigate, +2 for Destroyer, +3 for Cruiser, +4 for Battleship
    uint16 costsVersion;
    uint16 cost;
    uint16 modified; // 0 = false, anything else = true
    bool shiny;
    bool constructed;
    bool inFleet;
    bool isFreeShip;
    uint timestampDestroyed;
}

struct Costs {
    uint16 version;
    uint8 baseCost;
    uint8[] accuracy;
    uint8[] hull;
    uint8[] speed;
    // Items are uint8[4]
    uint8[] mainWeapon;
    uint8[] armor;
    uint8[] shields;
    uint8[] special;
    uint8[] variant; // indexed by traits.variant
}

// Be VERY CAREFUL giving negative movement!
// It can result in ships that can't move

// We don't need historical versions because this is just used to calculate
// attributes, which are done at the start of the game and stay the same

struct GunData {
    uint8 range;
    uint8 damage;
    int8 movement;
}

struct ArmorData {
    uint8 damageReduction;
    int8 movement;
}

struct ShieldData {
    uint8 damageReduction;
    int8 movement;
}

struct SpecialData {
    uint8 range;
    uint8 strength;
    int8 movement;
}

// Per-variant hull-piece bonuses (bridge/hull/engine) and per-variant special
// effects. Nested in a mapping (not an array) inside AttributesVersion since
// AttributesVersion only ever lives in storage (never copied to memory), so a
// mapping field is safe here.
struct VariantAttributeData {
    uint8[] foreAccuracy; // "bridge": indexed by traits.accuracy tier (0-2)
    uint8[] hull; // indexed by traits.hull tier (0-2)
    uint8[] engineSpeeds; // "engine": indexed by traits.speed tier (0-2)
    SpecialData[] specials; // indexed by Special enum (0-7)
}

struct AttributesVersion {
    uint16 version;
    uint8 baseHull;
    uint8 baseSpeed;
    GunData[] guns;
    ArmorData[] armors;
    ShieldData[] shields;
    mapping(uint16 => VariantAttributeData) variantData; // keyed by traits.variant
}

enum LobbyStatus {
    Open, // Lobby is open for joining
    FleetSelection, // Both players have joined, selecting fleets
    InGame // Game has started
}

// Basic lobby identification and ownership
struct LobbyBasic {
    uint id;
    address creator;
    uint costLimit;
    uint createdAt;
}

// Player and fleet information
struct LobbyPlayers {
    address joiner;
    address reservedJoiner; // Address of player this lobby is reserved for (if any)
    uint creatorFleetId;
    uint joinerFleetId;
    uint joinedAt;
    uint joinerFleetSetAt;
}

// Game configuration settings
struct LobbyGameConfig {
    bool creatorGoesFirst;
    uint turnTime; // Time in seconds for each turn
    uint selectedMapId; // ID of the preset map to use for this game
    uint maxScore; // Maximum score needed to win the game
}

// Lobby state and status
struct LobbyState {
    LobbyStatus status;
    uint gameStartedAt;
}

// Main lobby struct composed of smaller components
struct Lobby {
    LobbyBasic basic;
    LobbyPlayers players;
    LobbyGameConfig gameConfig;
    LobbyState state;
}

struct Fleet {
    uint id;
    uint lobbyId;
    address owner;
    uint[] shipIds;
    Position[] startingPositions;
    uint totalCost;
    bool isComplete;
}

struct PlayerLobbyState {
    uint activeLobbyId;
    uint activeLobbiesCount; // Track number of active lobbies
    bool hasActiveLobby;
    uint kickCount;
    uint lastKickTime;
}

enum ActionType {
    Pass,
    Shoot,
    Retreat,
    Assist,
    Special,
    // Innate to every ship of a given faction (traits.variant), independent
    // of loadout — unlike Special, which requires equipping a specific
    // equipment.special slot. Dispatched by faction, not by an equipped item.
    FactionAbility
}

// Last move information stored in game data
struct LastMove {
    uint shipId;
    int16 oldRow;
    int16 oldCol;
    int16 newRow;
    int16 newCol;
    ActionType actionType;
    uint targetShipId;
    uint timestamp; // When the move was made
}

// Player statistics for tracking wins and losses
struct PlayerStats {
    uint wins;
    uint losses;
    uint totalGames;
}

// Game result structure for tracking individual game outcomes
struct GameResult {
    uint gameId;
    address winner;
    address loser;
    uint timestamp;
}

